00344 // X11 does not include current pressed/released modifier key in 'mods' flags submitted by GLFW
00345 // See https://github.com/ocornut/imgui/issues/6034 and https://github.com/glfw/glfw/issues/1630
00346 static void ImGui_ImplGlfw_UpdateKeyModifiers(GLFWwindow* window)
00347 {
