00389 static int ImGui_ImplGlfw_TranslateUntranslatedKey(int key, int scancode)
00390 {
00391 #if GLFW_HAS_GETKEYNAME && !defined(EMSCRIPTEN_USE_EMBEDDED_GLFW3)
00392     // GLFW 3.1+ attempts to "untranslate" keys, which goes the opposite of what every other framework does, making using lettered shortcuts difficult.
00393     // (It had reasons to do so: namely GLFW is/was more likely to be used for WASD-type game controls rather than lettered shortcuts, but IHMO the 3.1 change could have been done differently)
00394     // See https://github.com/glfw/glfw/issues/1502 for details.
00395     // Adding a workaround to undo this (so our keys are translated->untranslated->translated, likely a lossy process).
00396     // This won't cover edge cases but this is at least going to cover common cases.
00397     if (key >= GLFW_KEY_KP_0 && key <= GLFW_KEY_KP_EQUAL)
00398         return key;
00399     GLFWerrorfun prev_error_callback = glfwSetErrorCallback(nullptr);
00400     const char* key_name = glfwGetKeyName(key, scancode);
00401     glfwSetErrorCallback(prev_error_callback);
00402 #if GLFW_HAS_GETERROR && !defined(EMSCRIPTEN_USE_EMBEDDED_GLFW3) // Eat errors (see #5908)
00403     (void)glfwGetError(nullptr);
00404 #endif
00405     if (key_name && key_name[0] != 0 && key_name[1] == 0)
00406     {
00407         const char char_names[] = "`-=[]\\,;\'./";
00408         const int char_keys[] = { GLFW_KEY_GRAVE_ACCENT, GLFW_KEY_MINUS, GLFW_KEY_EQUAL, GLFW_KEY_LEFT_BRACKET, GLFW_KEY_RIGHT_BRACKET, GLFW_KEY_BACKSLASH, GLFW_KEY_COMMA, GLFW_KEY_SEMICOLON, GLFW_KEY_APOSTROPHE, GLFW_KEY_PERIOD, GLFW_KEY_SLASH, 0 };
00409         IM_ASSERT(IM_ARRAYSIZE(char_names) == IM_ARRAYSIZE(char_keys));
00410         if (key_name[0] >= '0' && key_name[0] <= '9')               { key = GLFW_KEY_0 + (key_name[0] - '0'); }
00411         else if (key_name[0] >= 'A' && key_name[0] <= 'Z')          { key = GLFW_KEY_A + (key_name[0] - 'A'); }
00412         else if (key_name[0] >= 'a' && key_name[0] <= 'z')          { key = GLFW_KEY_A + (key_name[0] - 'a'); }
00413         else if (const char* p = strchr(char_names, key_name[0]))   { key = char_keys[p - char_names]; }
00414     }
00415     // if (action == GLFW_PRESS) printf("key %d scancode %d name '%s'\n", key, scancode, key_name);
00416 #else
00417     IM_UNUSED(scancode);
00418 #endif
00419     return key;
00420 }
