00422 void ImGui_ImplGlfw_KeyCallback(GLFWwindow* window, int keycode, int scancode, int action, int mods)
00423 {
00424     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00425     if (bd->PrevUserCallbackKey != nullptr && ImGui_ImplGlfw_ShouldChainCallback(window))
00426         bd->PrevUserCallbackKey(window, keycode, scancode, action, mods);
00427 
00428     if (action != GLFW_PRESS && action != GLFW_RELEASE)
00429         return;
00430 
00431     ImGui_ImplGlfw_UpdateKeyModifiers(window);
00432 
00433     if (keycode >= 0 && keycode < IM_ARRAYSIZE(bd->KeyOwnerWindows))
00434         bd->KeyOwnerWindows[keycode] = (action == GLFW_PRESS) ? window : nullptr;
00435 
00436     keycode = ImGui_ImplGlfw_TranslateUntranslatedKey(keycode, scancode);
00437 
00438     ImGuiIO& io = ImGui::GetIO();
00439     ImGuiKey imgui_key = ImGui_ImplGlfw_KeyToImGuiKey(keycode);
00440     io.AddKeyEvent(imgui_key, (action == GLFW_PRESS));
00441     io.SetKeyEventNativeData(imgui_key, keycode, scancode); // To support legacy indexing (<1.87 user code)
00442 }
