00472 // Workaround: X11 seems to send spurious Leave/Enter events which would make us lose our position,
00473 // so we back it up and restore on Leave/Enter (see https://github.com/ocornut/imgui/issues/4984)
00474 void ImGui_ImplGlfw_CursorEnterCallback(GLFWwindow* window, int entered)
00475 {
00476     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
