00482     {
00483         bd->MouseWindow = window;
00484         io.AddMousePosEvent(bd->LastValidMousePos.x, bd->LastValidMousePos.y);
00485     }
00486     else if (!entered && bd->MouseWindow == window)
00487     {
00488         bd->LastValidMousePos = io.MousePos;
00489         bd->MouseWindow = nullptr;
00490         io.AddMousePosEvent(-FLT_MAX, -FLT_MAX);
00491     }
