00510 #ifdef EMSCRIPTEN_USE_EMBEDDED_GLFW3
00511 static EM_BOOL ImGui_ImplEmscripten_WheelCallback(int, const EmscriptenWheelEvent* ev, void*)
00512 {
00513     // Mimic Emscripten_HandleWheel() in SDL.
00514     // Corresponding equivalent in GLFW JS emulation layer has incorrect quantizing preventing small values. See #6096
00515     float multiplier = 0.0f;
00516     if (ev->deltaMode == DOM_DELTA_PIXEL)       { multiplier = 1.0f / 100.0f; } // 100 pixels make up a step.
00517     else if (ev->deltaMode == DOM_DELTA_LINE)   { multiplier = 1.0f / 3.0f; }   // 3 lines make up a step.
00518     else if (ev->deltaMode == DOM_DELTA_PAGE)   { multiplier = 80.0f; }         // A page makes up 80 steps.
00519     float wheel_x = ev->deltaX * -multiplier;
00520     float wheel_y = ev->deltaY * -multiplier;
00521     ImGuiIO& io = ImGui::GetIO();
00522     io.AddMouseWheelEvent(wheel_x, wheel_y);
00523     //IMGUI_DEBUG_LOG("[Emsc] mode %d dx: %.2f, dy: %.2f, dz: %.2f --> feed %.2f %.2f\n", (int)ev->deltaMode, ev->deltaX, ev->deltaY, ev->deltaZ, wheel_x, wheel_y);
00524     return EM_TRUE;
00525 }
00526 #endif
