00588 static bool ImGui_ImplGlfw_Init(GLFWwindow* window, bool install_callbacks, GlfwClientApi client_api)
00589 {
00590     ImGuiIO& io = ImGui::GetIO();
00591     IMGUI_CHECKVERSION();
00592     IM_ASSERT(io.BackendPlatformUserData == nullptr && "Already initialized a platform backend!");
00593     //printf("GLFW_VERSION: %d.%d.%d (%d)", GLFW_VERSION_MAJOR, GLFW_VERSION_MINOR, GLFW_VERSION_REVISION, GLFW_VERSION_COMBINED);
00594 
00595     // Setup backend capabilities flags
00596     ImGui_ImplGlfw_Data* bd = IM_NEW(ImGui_ImplGlfw_Data)();
00597     io.BackendPlatformUserData = (void*)bd;
00598     io.BackendPlatformName = "imgui_impl_glfw";
00599     io.BackendFlags |= ImGuiBackendFlags_HasMouseCursors;         // We can honor GetMouseCursor() values (optional)
00600     io.BackendFlags |= ImGuiBackendFlags_HasSetMousePos;          // We can honor io.WantSetMousePos requests (optional, rarely used)
00601 #ifndef __EMSCRIPTEN__
00602     io.BackendFlags |= ImGuiBackendFlags_PlatformHasViewports;    // We can create multi-viewports on the Platform side (optional)
00603 #endif
00604 #if GLFW_HAS_MOUSE_PASSTHROUGH || GLFW_HAS_WINDOW_HOVERED
00605     io.BackendFlags |= ImGuiBackendFlags_HasMouseHoveredViewport; // We can call io.AddMouseViewportEvent() with correct data (optional)
00606 #endif
00607 
00608     bd->Window = window;
00609     bd->Time = 0.0;
00610     bd->WantUpdateMonitors = true;
00611 
00612     io.SetClipboardTextFn = ImGui_ImplGlfw_SetClipboardText;
00613     io.GetClipboardTextFn = ImGui_ImplGlfw_GetClipboardText;
00614     io.ClipboardUserData = bd->Window;
00615 #ifdef __EMSCRIPTEN__
00616     io.PlatformOpenInShellFn = [](ImGuiContext*, const char* url) { ImGui_ImplGlfw_EmscriptenOpenURL(url); return true; };
00617 #endif
00618 
00619     // Create mouse cursors
00620     // (By design, on X11 cursors are user configurable and some cursors may be missing. When a cursor doesn't exist,
00621     // GLFW will emit an error which will often be printed by the app, so we temporarily disable error reporting.
00622     // Missing cursors will return nullptr and our _UpdateMouseCursor() function will use the Arrow cursor instead.)
00623     GLFWerrorfun prev_error_callback = glfwSetErrorCallback(nullptr);
00624     bd->MouseCursors[ImGuiMouseCursor_Arrow] = glfwCreateStandardCursor(GLFW_ARROW_CURSOR);
00625     bd->MouseCursors[ImGuiMouseCursor_TextInput] = glfwCreateStandardCursor(GLFW_IBEAM_CURSOR);
00626     bd->MouseCursors[ImGuiMouseCursor_ResizeNS] = glfwCreateStandardCursor(GLFW_VRESIZE_CURSOR);
00627     bd->MouseCursors[ImGuiMouseCursor_ResizeEW] = glfwCreateStandardCursor(GLFW_HRESIZE_CURSOR);
00628     bd->MouseCursors[ImGuiMouseCursor_Hand] = glfwCreateStandardCursor(GLFW_HAND_CURSOR);
00629 #if GLFW_HAS_NEW_CURSORS
00630     bd->MouseCursors[ImGuiMouseCursor_ResizeAll] = glfwCreateStandardCursor(GLFW_RESIZE_ALL_CURSOR);
00631     bd->MouseCursors[ImGuiMouseCursor_ResizeNESW] = glfwCreateStandardCursor(GLFW_RESIZE_NESW_CURSOR);
00632     bd->MouseCursors[ImGuiMouseCursor_ResizeNWSE] = glfwCreateStandardCursor(GLFW_RESIZE_NWSE_CURSOR);
00633     bd->MouseCursors[ImGuiMouseCursor_NotAllowed] = glfwCreateStandardCursor(GLFW_NOT_ALLOWED_CURSOR);
00634 #else
00635     bd->MouseCursors[ImGuiMouseCursor_ResizeAll] = glfwCreateStandardCursor(GLFW_ARROW_CURSOR);
00636     bd->MouseCursors[ImGuiMouseCursor_ResizeNESW] = glfwCreateStandardCursor(GLFW_ARROW_CURSOR);
00637     bd->MouseCursors[ImGuiMouseCursor_ResizeNWSE] = glfwCreateStandardCursor(GLFW_ARROW_CURSOR);
00638     bd->MouseCursors[ImGuiMouseCursor_NotAllowed] = glfwCreateStandardCursor(GLFW_ARROW_CURSOR);
00639 #endif
00640     glfwSetErrorCallback(prev_error_callback);
00641 #if GLFW_HAS_GETERROR && !defined(__EMSCRIPTEN__) // Eat errors (see #5908)
00642     (void)glfwGetError(nullptr);
00643 #endif
00644 
00645     // Chain GLFW callbacks: our callbacks will call the user's previously installed callbacks, if any.
00646     if (install_callbacks)
00647         ImGui_ImplGlfw_InstallCallbacks(window);
00648 
00649     // Update monitors the first time (note: monitor callback are broken in GLFW 3.2 and earlier, see github.com/glfw/glfw/issues/784)
00650     ImGui_ImplGlfw_UpdateMonitors();
00651     glfwSetMonitorCallback(ImGui_ImplGlfw_MonitorCallback);
00652 
00653     // Set platform dependent data in viewport
00654     ImGuiViewport* main_viewport = ImGui::GetMainViewport();
00655     main_viewport->PlatformHandle = (void*)bd->Window;
00656 #ifdef _WIN32
00657     main_viewport->PlatformHandleRaw = glfwGetWin32Window(bd->Window);
00658 #elif defined(__APPLE__)
00659     main_viewport->PlatformHandleRaw = (void*)glfwGetCocoaWindow(bd->Window);
00660 #else
00661     IM_UNUSED(main_viewport);
00662 #endif
00663     if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
00664         ImGui_ImplGlfw_InitPlatformInterface();
00665 
00666     // Windows: register a WndProc hook so we can intercept some messages.
00667 #ifdef _WIN32
00668     bd->PrevWndProc = (WNDPROC)::GetWindowLongPtrW((HWND)main_viewport->PlatformHandleRaw, GWLP_WNDPROC);
00669     IM_ASSERT(bd->PrevWndProc != nullptr);
00670     ::SetWindowLongPtrW((HWND)main_viewport->PlatformHandleRaw, GWLP_WNDPROC, (LONG_PTR)ImGui_ImplGlfw_WndProc);
00671 #endif
00672 
00673     bd->ClientApi = client_api;
00674     return true;
00675 }
