00692 void ImGui_ImplGlfw_Shutdown()
00693 {
00694     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00695     IM_ASSERT(bd != nullptr && "No platform backend to shutdown, or already shutdown?");
00696     ImGuiIO& io = ImGui::GetIO();
00697 
00698     ImGui_ImplGlfw_ShutdownPlatformInterface();
00699 
00700     if (bd->InstalledCallbacks)
00701         ImGui_ImplGlfw_RestoreCallbacks(bd->Window);
00702 #ifdef EMSCRIPTEN_USE_EMBEDDED_GLFW3
00703     if (bd->CanvasSelector)
00704         emscripten_set_wheel_callback(bd->CanvasSelector, nullptr, false, nullptr);
00705 #endif
00706 
00707     for (ImGuiMouseCursor cursor_n = 0; cursor_n < ImGuiMouseCursor_COUNT; cursor_n++)
00708         glfwDestroyCursor(bd->MouseCursors[cursor_n]);
00709 
00710     // Windows: restore our WndProc hook
00711 #ifdef _WIN32
00712     ImGuiViewport* main_viewport = ImGui::GetMainViewport();
00713     ::SetWindowLongPtrW((HWND)main_viewport->PlatformHandleRaw, GWLP_WNDPROC, (LONG_PTR)bd->PrevWndProc);
00714     bd->PrevWndProc = nullptr;
00715 #endif
00716 
00717     io.BackendPlatformName = nullptr;
00718     io.BackendPlatformUserData = nullptr;
00719     io.BackendFlags &= ~(ImGuiBackendFlags_HasMouseCursors | ImGuiBackendFlags_HasSetMousePos | ImGuiBackendFlags_HasGamepad | ImGuiBackendFlags_PlatformHasViewports | ImGuiBackendFlags_HasMouseHoveredViewport);
00720     IM_DELETE(bd);
00721 }
