00723 static void ImGui_ImplGlfw_UpdateMouseData()
00724 {
00725     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00726     ImGuiIO& io = ImGui::GetIO();
00727     ImGuiPlatformIO& platform_io = ImGui::GetPlatformIO();
00728 
00729     ImGuiID mouse_viewport_id = 0;
00730     const ImVec2 mouse_pos_prev = io.MousePos;
00731     for (int n = 0; n < platform_io.Viewports.Size; n++)
00732     {
00733         ImGuiViewport* viewport = platform_io.Viewports[n];
00734         GLFWwindow* window = (GLFWwindow*)viewport->PlatformHandle;
00735 
00736 #ifdef EMSCRIPTEN_USE_EMBEDDED_GLFW3
00737         const bool is_window_focused = true;
00738 #else
00739         const bool is_window_focused = glfwGetWindowAttrib(window, GLFW_FOCUSED) != 0;
00740 #endif
00741         if (is_window_focused)
00742         {
00743             // (Optional) Set OS mouse position from Dear ImGui if requested (rarely used, only when ImGuiConfigFlags_NavEnableSetMousePos is enabled by user)
00744             // When multi-viewports are enabled, all Dear ImGui positions are same as OS positions.
00745             if (io.WantSetMousePos)
00746                 glfwSetCursorPos(window, (double)(mouse_pos_prev.x - viewport->Pos.x), (double)(mouse_pos_prev.y - viewport->Pos.y));
00747 
00748             // (Optional) Fallback to provide mouse position when focused (ImGui_ImplGlfw_CursorPosCallback already provides this when hovered or captured)
00749             if (bd->MouseWindow == nullptr)
00750             {
00751                 double mouse_x, mouse_y;
00752                 glfwGetCursorPos(window, &mouse_x, &mouse_y);
00753                 if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
00754                 {
00755                     // Single viewport mode: mouse position in client window coordinates (io.MousePos is (0,0) when the mouse is on the upper-left corner of the app window)
00756                     // Multi-viewport mode: mouse position in OS absolute coordinates (io.MousePos is (0,0) when the mouse is on the upper-left of the primary monitor)
00757                     int window_x, window_y;
00758                     glfwGetWindowPos(window, &window_x, &window_y);
00759                     mouse_x += window_x;
00760                     mouse_y += window_y;
00761                 }
00762                 bd->LastValidMousePos = ImVec2((float)mouse_x, (float)mouse_y);
00763                 io.AddMousePosEvent((float)mouse_x, (float)mouse_y);
00764             }
00765         }
00766 
00767         // (Optional) When using multiple viewports: call io.AddMouseViewportEvent() with the viewport the OS mouse cursor is hovering.
00768         // If ImGuiBackendFlags_HasMouseHoveredViewport is not set by the backend, Dear imGui will ignore this field and infer the information using its flawed heuristic.
00769         // - [X] GLFW >= 3.3 backend ON WINDOWS ONLY does correctly ignore viewports with the _NoInputs flag (since we implement hit via our WndProc hook)
00770         //       On other platforms we rely on the library fallbacking to its own search when reporting a viewport with _NoInputs flag.
00771         // - [!] GLFW <= 3.2 backend CANNOT correctly ignore viewports with the _NoInputs flag, and CANNOT reported Hovered Viewport because of mouse capture.
00772         //       Some backend are not able to handle that correctly. If a backend report an hovered viewport that has the _NoInputs flag (e.g. when dragging a window
00773         //       for docking, the viewport has the _NoInputs flag in order to allow us to find the viewport under), then Dear ImGui is forced to ignore the value reported
00774         //       by the backend, and use its flawed heuristic to guess the viewport behind.
00775         // - [X] GLFW backend correctly reports this regardless of another viewport behind focused and dragged from (we need this to find a useful drag and drop target).
00776         // FIXME: This is currently only correct on Win32. See what we do below with the WM_NCHITTEST, missing an equivalent for other systems.
00777         // See https://github.com/glfw/glfw/issues/1236 if you want to help in making this a GLFW feature.
00778 #if GLFW_HAS_MOUSE_PASSTHROUGH
00779         const bool window_no_input = (viewport->Flags & ImGuiViewportFlags_NoInputs) != 0;
00780         glfwSetWindowAttrib(window, GLFW_MOUSE_PASSTHROUGH, window_no_input);
00781 #endif
00782 #if GLFW_HAS_MOUSE_PASSTHROUGH || GLFW_HAS_WINDOW_HOVERED
00783         if (glfwGetWindowAttrib(window, GLFW_HOVERED))
00784             mouse_viewport_id = viewport->ID;
00785 #else
00786         // We cannot use bd->MouseWindow maintained from CursorEnter/Leave callbacks, because it is locked to the window capturing mouse.
00787 #endif
00788     }
00789 
00790     if (io.BackendFlags & ImGuiBackendFlags_HasMouseHoveredViewport)
00791         io.AddMouseViewportEvent(mouse_viewport_id);
00792 }
00793 
00794 static void ImGui_ImplGlfw_UpdateMouseCursor()
00795 {
00796     ImGuiIO& io = ImGui::GetIO();
00797     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00798     if ((io.ConfigFlags & ImGuiConfigFlags_NoMouseCursorChange) || glfwGetInputMode(bd->Window, GLFW_CURSOR) == GLFW_CURSOR_DISABLED)
00799         return;
00800 
00801     ImGuiMouseCursor imgui_cursor = ImGui::GetMouseCursor();
00802     ImGuiPlatformIO& platform_io = ImGui::GetPlatformIO();
00803     for (int n = 0; n < platform_io.Viewports.Size; n++)
00804     {
00805         GLFWwindow* window = (GLFWwindow*)platform_io.Viewports[n]->PlatformHandle;
00806         if (imgui_cursor == ImGuiMouseCursor_None || io.MouseDrawCursor)
00807         {
00808             // Hide OS mouse cursor if imgui is drawing it or if it wants no cursor
00809             glfwSetInputMode(window, GLFW_CURSOR, GLFW_CURSOR_HIDDEN);
00810         }
00811         else
00812         {
00813             // Show OS mouse cursor
00814             // FIXME-PLATFORM: Unfocused windows seems to fail changing the mouse cursor with GLFW 3.2, but 3.3 works here.
00815             glfwSetCursor(window, bd->MouseCursors[imgui_cursor] ? bd->MouseCursors[imgui_cursor] : bd->MouseCursors[ImGuiMouseCursor_Arrow]);
00816             glfwSetInputMode(window, GLFW_CURSOR, GLFW_CURSOR_NORMAL);
00817         }
00818     }
00819 }
