00874 static void ImGui_ImplGlfw_UpdateMonitors()
00875 {
00876     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00877     ImGuiPlatformIO& platform_io = ImGui::GetPlatformIO();
00878     bd->WantUpdateMonitors = false;
00879 
00880     int monitors_count = 0;
00881     GLFWmonitor** glfw_monitors = glfwGetMonitors(&monitors_count);
00882     if (monitors_count == 0) // Preserve existing monitor list if there are none. Happens on macOS sleeping (#5683)
00883         return;
00884 
00885     platform_io.Monitors.resize(0);
00886     for (int n = 0; n < monitors_count; n++)
00887     {
00888         ImGuiPlatformMonitor monitor;
00889         int x, y;
00890         glfwGetMonitorPos(glfw_monitors[n], &x, &y);
00891         const GLFWvidmode* vid_mode = glfwGetVideoMode(glfw_monitors[n]);
00892         if (vid_mode == nullptr)
00893             continue; // Failed to get Video mode (e.g. Emscripten does not support this function)
00894         monitor.MainPos = monitor.WorkPos = ImVec2((float)x, (float)y);
00895         monitor.MainSize = monitor.WorkSize = ImVec2((float)vid_mode->width, (float)vid_mode->height);
00896 #if GLFW_HAS_MONITOR_WORK_AREA
00897         int w, h;
00898         glfwGetMonitorWorkarea(glfw_monitors[n], &x, &y, &w, &h);
00899         if (w > 0 && h > 0) // Workaround a small GLFW issue reporting zero on monitor changes: https://github.com/glfw/glfw/pull/1761
00900         {
00901             monitor.WorkPos = ImVec2((float)x, (float)y);
00902             monitor.WorkSize = ImVec2((float)w, (float)h);
00903         }
00904 #endif
00905 #if GLFW_HAS_PER_MONITOR_DPI
00906         // Warning: the validity of monitor DPI information on Windows depends on the application DPI awareness settings, which generally needs to be set in the manifest or at runtime.
00907         float x_scale, y_scale;
00908         glfwGetMonitorContentScale(glfw_monitors[n], &x_scale, &y_scale);
00909         monitor.DpiScale = x_scale;
00910 #endif
00911         monitor.PlatformHandle = (void*)glfw_monitors[n]; // [...] GLFW doc states: "guaranteed to be valid only until the monitor configuration changes"
00912         platform_io.Monitors.push_back(monitor);
00913     }
00914 }
