00959 static EM_BOOL ImGui_ImplGlfw_OnCanvasSizeChange(int event_type, const EmscriptenUiEvent* event, void* user_data)
00960 {
00961     ImGui_ImplGlfw_Data* bd = (ImGui_ImplGlfw_Data*)user_data;
00962     double canvas_width, canvas_height;
00963     emscripten_get_element_css_size(bd->CanvasSelector, &canvas_width, &canvas_height);
00964     glfwSetWindowSize(bd->Window, (int)canvas_width, (int)canvas_height);
00965     return true;
