00968 static EM_BOOL ImGui_ImplEmscripten_FullscreenChangeCallback(int event_type, const EmscriptenFullscreenChangeEvent* event, void* user_data)
00969 {
00970     ImGui_ImplGlfw_Data* bd = (ImGui_ImplGlfw_Data*)user_data;
00971     double canvas_width, canvas_height;
00972     emscripten_get_element_css_size(bd->CanvasSelector, &canvas_width, &canvas_height);
00973     glfwSetWindowSize(bd->Window, (int)canvas_width, (int)canvas_height);
00974     return true;
00975 }
00976 
00977 // 'canvas_selector' is a CSS selector. The event listener is applied to the first element that matches the query.
00978 // STRING MUST PERSIST FOR THE APPLICATION DURATION. PLEASE USE A STRING LITERAL OR ENSURE POINTER WILL STAY VALID.
00979 void ImGui_ImplGlfw_InstallEmscriptenCallbacks(GLFWwindow*, const char* canvas_selector)
00980 {
00981     IM_ASSERT(canvas_selector != nullptr);
00982     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
00983     IM_ASSERT(bd != nullptr && "Context or backend not initialized! Did you call ImGui_ImplGlfw_InitForXXX()?");
00984 
00985     bd->CanvasSelector = canvas_selector;
00986     emscripten_set_resize_callback(EMSCRIPTEN_EVENT_TARGET_WINDOW, bd, false, ImGui_ImplGlfw_OnCanvasSizeChange);
00987     emscripten_set_fullscreenchange_callback(EMSCRIPTEN_EVENT_TARGET_DOCUMENT, bd, false, ImGui_ImplEmscripten_FullscreenChangeCallback);
00988 
00989     // Change the size of the GLFW window according to the size of the canvas
00990     ImGui_ImplGlfw_OnCanvasSizeChange(EMSCRIPTEN_EVENT_RESIZE, {}, bd);
00991 
00992     // Register Emscripten Wheel callback to workaround issue in Emscripten GLFW Emulation (#6096)
00993     // We intentionally do not check 'if (install_callbacks)' here, as some users may set it to false and call GLFW callback themselves.
00994     // FIXME: May break chaining in case user registered their own Emscripten callback?
00995     emscripten_set_wheel_callback(bd->CanvasSelector, nullptr, false, ImGui_ImplEmscripten_WheelCallback);
00996 }
00997 #elif defined(EMSCRIPTEN_USE_PORT_CONTRIB_GLFW3)
00998 // When using --use-port=contrib.glfw3 for the GLFW implementation, you can override the behavior of this call
00999 // by invoking emscripten_glfw_make_canvas_resizable afterward.
01000 // See https://github.com/pongasoft/emscripten-glfw/blob/master/docs/Usage.md#how-to-make-the-canvas-resizable-by-the-user for an explanation
01001 void ImGui_ImplGlfw_InstallEmscriptenCallbacks(GLFWwindow* window, const char* canvas_selector)
01002 {
01003   GLFWwindow* w = (GLFWwindow*)(EM_ASM_INT({ return Module.glfwGetWindow(UTF8ToString($0)); }, canvas_selector));
01004   IM_ASSERT(window == w); // Sanity check
01005   IM_UNUSED(w);
01006   emscripten_glfw_make_canvas_resizable(window, "window", nullptr);
01007 }
01008 #endif // #ifdef EMSCRIPTEN_USE_PORT_CONTRIB_GLFW3
