01011 //--------------------------------------------------------------------------------------------------------
01012 // MULTI-VIEWPORT / PLATFORM INTERFACE SUPPORT
01013 // This is an _advanced_ and _optional_ feature, allowing the backend to create and handle multiple viewports simultaneously.
01014 // If you are new to dear imgui or creating a new binding for dear imgui, it is recommended that you completely ignore this section first..
01015 //--------------------------------------------------------------------------------------------------------
01016 
01017 // Helper structure we store in the void* RendererUserData field of each ImGuiViewport to easily retrieve our backend data.
01018 struct ImGui_ImplGlfw_ViewportData
01019 {
01020     GLFWwindow* Window;
01021     bool        WindowOwned;
01022     int         IgnoreWindowPosEventFrame;
01023     int         IgnoreWindowSizeEventFrame;
01024 #ifdef _WIN32
01025     WNDPROC     PrevWndProc;
01026 #endif
01027 
01028     ImGui_ImplGlfw_ViewportData()  { memset(this, 0, sizeof(*this)); IgnoreWindowSizeEventFrame = IgnoreWindowPosEventFrame = -1; }
01029     ~ImGui_ImplGlfw_ViewportData() { IM_ASSERT(Window == nullptr); }
01030 };
01031 
01032 static void ImGui_ImplGlfw_WindowCloseCallback(GLFWwindow* window)
01033 {
01034     if (ImGuiViewport* viewport = ImGui::FindViewportByPlatformHandle(window))
01035         viewport->PlatformRequestClose = true;
01036 }
01037 
01038 // GLFW may dispatch window pos/size events after calling glfwSetWindowPos()/glfwSetWindowSize().
01039 // However: depending on the platform the callback may be invoked at different time:
01040 // - on Windows it appears to be called within the glfwSetWindowPos()/glfwSetWindowSize() call
01041 // - on Linux it is queued and invoked during glfwPollEvents()
01042 // Because the event doesn't always fire on glfwSetWindowXXX() we use a frame counter tag to only
01043 // ignore recent glfwSetWindowXXX() calls.
01044 static void ImGui_ImplGlfw_WindowPosCallback(GLFWwindow* window, int, int)
01045 {
01046     if (ImGuiViewport* viewport = ImGui::FindViewportByPlatformHandle(window))
01047     {
01048         if (ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData)
01049         {
01050             bool ignore_event = (ImGui::GetFrameCount() <= vd->IgnoreWindowPosEventFrame + 1);
01051             //data->IgnoreWindowPosEventFrame = -1;
01052             if (ignore_event)
01053                 return;
01054         }
01055         viewport->PlatformRequestMove = true;
01056     }
01057 }
01058 
01059 static void ImGui_ImplGlfw_WindowSizeCallback(GLFWwindow* window, int, int)
01060 {
01061     if (ImGuiViewport* viewport = ImGui::FindViewportByPlatformHandle(window))
01062     {
01063         if (ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData)
01064         {
01065             bool ignore_event = (ImGui::GetFrameCount() <= vd->IgnoreWindowSizeEventFrame + 1);
01066             //data->IgnoreWindowSizeEventFrame = -1;
01067             if (ignore_event)
01068                 return;
01069         }
01070         viewport->PlatformRequestResize = true;
01071     }
01072 }
