01074 static void ImGui_ImplGlfw_CreateWindow(ImGuiViewport* viewport)
01075 {
01076     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
01077     ImGui_ImplGlfw_ViewportData* vd = IM_NEW(ImGui_ImplGlfw_ViewportData)();
01078     viewport->PlatformUserData = vd;
01079 
01080     // GLFW 3.2 unfortunately always set focus on glfwCreateWindow() if GLFW_VISIBLE is set, regardless of GLFW_FOCUSED
01081     // With GLFW 3.3, the hint GLFW_FOCUS_ON_SHOW fixes this problem
01082     glfwWindowHint(GLFW_VISIBLE, false);
01083     glfwWindowHint(GLFW_FOCUSED, false);
01084 #if GLFW_HAS_FOCUS_ON_SHOW
01085     glfwWindowHint(GLFW_FOCUS_ON_SHOW, false);
01086  #endif
01087     glfwWindowHint(GLFW_DECORATED, (viewport->Flags & ImGuiViewportFlags_NoDecoration) ? false : true);
01088 #if GLFW_HAS_WINDOW_TOPMOST
01089     glfwWindowHint(GLFW_FLOATING, (viewport->Flags & ImGuiViewportFlags_TopMost) ? true : false);
01090 #endif
01091     GLFWwindow* share_window = (bd->ClientApi == GlfwClientApi_OpenGL) ? bd->Window : nullptr;
01092     vd->Window = glfwCreateWindow((int)viewport->Size.x, (int)viewport->Size.y, "No Title Yet", nullptr, share_window);
01093     vd->WindowOwned = true;
01094     viewport->PlatformHandle = (void*)vd->Window;
01095 #ifdef _WIN32
01096     viewport->PlatformHandleRaw = glfwGetWin32Window(vd->Window);
01097 #elif defined(__APPLE__)
01098     viewport->PlatformHandleRaw = (void*)glfwGetCocoaWindow(vd->Window);
01099 #endif
01100     glfwSetWindowPos(vd->Window, (int)viewport->Pos.x, (int)viewport->Pos.y);
01101 
01102     // Install GLFW callbacks for secondary viewports
01103     glfwSetWindowFocusCallback(vd->Window, ImGui_ImplGlfw_WindowFocusCallback);
01104     glfwSetCursorEnterCallback(vd->Window, ImGui_ImplGlfw_CursorEnterCallback);
01105     glfwSetCursorPosCallback(vd->Window, ImGui_ImplGlfw_CursorPosCallback);
01106     glfwSetMouseButtonCallback(vd->Window, ImGui_ImplGlfw_MouseButtonCallback);
01107     glfwSetScrollCallback(vd->Window, ImGui_ImplGlfw_ScrollCallback);
01108     glfwSetKeyCallback(vd->Window, ImGui_ImplGlfw_KeyCallback);
01109     glfwSetCharCallback(vd->Window, ImGui_ImplGlfw_CharCallback);
01110     glfwSetWindowCloseCallback(vd->Window, ImGui_ImplGlfw_WindowCloseCallback);
01111     glfwSetWindowPosCallback(vd->Window, ImGui_ImplGlfw_WindowPosCallback);
01112     glfwSetWindowSizeCallback(vd->Window, ImGui_ImplGlfw_WindowSizeCallback);
01113     if (bd->ClientApi == GlfwClientApi_OpenGL)
01114     {
01115         glfwMakeContextCurrent(vd->Window);
01116         glfwSwapInterval(0);
01117     }
01118 }
