01120 static void ImGui_ImplGlfw_DestroyWindow(ImGuiViewport* viewport)
01121 {
01122     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
01123     if (ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData)
01124     {
01125         if (vd->WindowOwned)
01126         {
01127 #if !GLFW_HAS_MOUSE_PASSTHROUGH && GLFW_HAS_WINDOW_HOVERED && defined(_WIN32)
01128             HWND hwnd = (HWND)viewport->PlatformHandleRaw;
01129             ::RemovePropA(hwnd, "IMGUI_VIEWPORT");
01130 #endif
01131 
01132             // Release any keys that were pressed in the window being destroyed and are still held down,
01133             // because we will not receive any release events after window is destroyed.
01134             for (int i = 0; i < IM_ARRAYSIZE(bd->KeyOwnerWindows); i++)
01135                 if (bd->KeyOwnerWindows[i] == vd->Window)
01136                     ImGui_ImplGlfw_KeyCallback(vd->Window, i, 0, GLFW_RELEASE, 0); // Later params are only used for main viewport, on which this function is never called.
01137 
01138             glfwDestroyWindow(vd->Window);
01139         }
01140         vd->Window = nullptr;
01141         IM_DELETE(vd);
01142     }
01143     viewport->PlatformUserData = viewport->PlatformHandle = nullptr;
01144 }
