01146 static void ImGui_ImplGlfw_ShowWindow(ImGuiViewport* viewport)
01147 {
01148     ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData;
01149 
01150 #if defined(_WIN32)
01151     // GLFW hack: Hide icon from task bar
01152     HWND hwnd = (HWND)viewport->PlatformHandleRaw;
01153     if (viewport->Flags & ImGuiViewportFlags_NoTaskBarIcon)
01154     {
01155         LONG ex_style = ::GetWindowLong(hwnd, GWL_EXSTYLE);
01156         ex_style &= ~WS_EX_APPWINDOW;
01157         ex_style |= WS_EX_TOOLWINDOW;
01158         ::SetWindowLong(hwnd, GWL_EXSTYLE, ex_style);
01159     }
01160 
01161     // GLFW hack: install hook for WM_NCHITTEST message handler
01162 #if !GLFW_HAS_MOUSE_PASSTHROUGH && GLFW_HAS_WINDOW_HOVERED && defined(_WIN32)
01163     ::SetPropA(hwnd, "IMGUI_VIEWPORT", viewport);
01164     vd->PrevWndProc = (WNDPROC)::GetWindowLongPtrW(hwnd, GWLP_WNDPROC);
01165     ::SetWindowLongPtrW(hwnd, GWLP_WNDPROC, (LONG_PTR)ImGui_ImplGlfw_WndProc);
01166 #endif
01167 
01168 #if !GLFW_HAS_FOCUS_ON_SHOW
01169     // GLFW hack: GLFW 3.2 has a bug where glfwShowWindow() also activates/focus the window.
01170     // The fix was pushed to GLFW repository on 2018/01/09 and should be included in GLFW 3.3 via a GLFW_FOCUS_ON_SHOW window attribute.
01171     // See https://github.com/glfw/glfw/issues/1189
01172     // FIXME-VIEWPORT: Implement same work-around for Linux/OSX in the meanwhile.
01173     if (viewport->Flags & ImGuiViewportFlags_NoFocusOnAppearing)
01174     {
01175         ::ShowWindow(hwnd, SW_SHOWNA);
01176         return;
01177     }
01178 #endif
01179 #endif
01180 
01181     glfwShowWindow(vd->Window);
01182 }
