01207 static void ImGui_ImplGlfw_SetWindowSize(ImGuiViewport* viewport, ImVec2 size)
01208 {
01209     ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData;
01210 #if __APPLE__ && !GLFW_HAS_OSX_WINDOW_POS_FIX
01211     // Native OS windows are positioned from the bottom-left corner on macOS, whereas on other platforms they are
01212     // positioned from the upper-left corner. GLFW makes an effort to convert macOS style coordinates, however it
01213     // doesn't handle it when changing size. We are manually moving the window in order for changes of size to be based
01214     // on the upper-left corner.
01215     int x, y, width, height;
01216     glfwGetWindowPos(vd->Window, &x, &y);
01217     glfwGetWindowSize(vd->Window, &width, &height);
01218     glfwSetWindowPos(vd->Window, x, y - height + size.y);
01219 #endif
01220     vd->IgnoreWindowSizeEventFrame = ImGui::GetFrameCount();
01221     glfwSetWindowSize(vd->Window, (int)size.x, (int)size.y);
01222 }
