01280 //--------------------------------------------------------------------------------------------------------
01281 // Vulkan support (the Vulkan renderer needs to call a platform-side support function to create the surface)
01282 //--------------------------------------------------------------------------------------------------------
01283 
01284 // Avoid including <vulkan.h> so we can build without it
01285 #if GLFW_HAS_VULKAN
01286 #ifndef VULKAN_H_
01287 #define VK_DEFINE_HANDLE(object) typedef struct object##_T* object;
01288 #if defined(__LP64__) || defined(_WIN64) || defined(__x86_64__) || defined(_M_X64) || defined(__ia64) || defined (_M_IA64) || defined(__aarch64__) || defined(__powerpc64__)
01289 #define VK_DEFINE_NON_DISPATCHABLE_HANDLE(object) typedef struct object##_T *object;
01290 #else
01291 #define VK_DEFINE_NON_DISPATCHABLE_HANDLE(object) typedef uint64_t object;
01292 #endif
01293 VK_DEFINE_HANDLE(VkInstance)
01294 VK_DEFINE_NON_DISPATCHABLE_HANDLE(VkSurfaceKHR)
01295 struct VkAllocationCallbacks;
01296 enum VkResult { VK_RESULT_MAX_ENUM = 0x7FFFFFFF };
01297 #endif // VULKAN_H_
01298 extern "C" { extern GLFWAPI VkResult glfwCreateWindowSurface(VkInstance instance, GLFWwindow* window, const VkAllocationCallbacks* allocator, VkSurfaceKHR* surface); }
01299 static int ImGui_ImplGlfw_CreateVkSurface(ImGuiViewport* viewport, ImU64 vk_instance, const void* vk_allocator, ImU64* out_vk_surface)
01300 {
01301     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
01302     ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData;
01303     IM_UNUSED(bd);
01304     IM_ASSERT(bd->ClientApi == GlfwClientApi_Vulkan);
01305     VkResult err = glfwCreateWindowSurface((VkInstance)vk_instance, vd->Window, (const VkAllocationCallbacks*)vk_allocator, (VkSurfaceKHR*)out_vk_surface);
01306     return (int)err;
01307 }
01308 #endif // GLFW_HAS_VULKAN
01309 
01310 static void ImGui_ImplGlfw_InitPlatformInterface()
01311 {
01312     // Register platform interface (will be coupled with a renderer interface)
01313     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
01314     ImGuiPlatformIO& platform_io = ImGui::GetPlatformIO();
01315     platform_io.Platform_CreateWindow = ImGui_ImplGlfw_CreateWindow;
01316     platform_io.Platform_DestroyWindow = ImGui_ImplGlfw_DestroyWindow;
01317     platform_io.Platform_ShowWindow = ImGui_ImplGlfw_ShowWindow;
01318     platform_io.Platform_SetWindowPos = ImGui_ImplGlfw_SetWindowPos;
01319     platform_io.Platform_GetWindowPos = ImGui_ImplGlfw_GetWindowPos;
01320     platform_io.Platform_SetWindowSize = ImGui_ImplGlfw_SetWindowSize;
01321     platform_io.Platform_GetWindowSize = ImGui_ImplGlfw_GetWindowSize;
01322     platform_io.Platform_SetWindowFocus = ImGui_ImplGlfw_SetWindowFocus;
01323     platform_io.Platform_GetWindowFocus = ImGui_ImplGlfw_GetWindowFocus;
01324     platform_io.Platform_GetWindowMinimized = ImGui_ImplGlfw_GetWindowMinimized;
01325     platform_io.Platform_SetWindowTitle = ImGui_ImplGlfw_SetWindowTitle;
01326     platform_io.Platform_RenderWindow = ImGui_ImplGlfw_RenderWindow;
01327     platform_io.Platform_SwapBuffers = ImGui_ImplGlfw_SwapBuffers;
01328 #if GLFW_HAS_WINDOW_ALPHA
01329     platform_io.Platform_SetWindowAlpha = ImGui_ImplGlfw_SetWindowAlpha;
01330 #endif
01331 #if GLFW_HAS_VULKAN
01332     platform_io.Platform_CreateVkSurface = ImGui_ImplGlfw_CreateVkSurface;
01333 #endif
01334 
01335     // Register main window handle (which is owned by the main application, not by us)
01336     // This is mostly for simplicity and consistency, so that our code (e.g. mouse handling etc.) can use same logic for main and secondary viewports.
01337     ImGuiViewport* main_viewport = ImGui::GetMainViewport();
01338     ImGui_ImplGlfw_ViewportData* vd = IM_NEW(ImGui_ImplGlfw_ViewportData)();
01339     vd->Window = bd->Window;
01340     vd->WindowOwned = false;
01341     main_viewport->PlatformUserData = vd;
01342     main_viewport->PlatformHandle = (void*)bd->Window;
01343 }
01344 
01345 static void ImGui_ImplGlfw_ShutdownPlatformInterface()
01346 {
01347     ImGui::DestroyPlatformWindows();
01348 }
