01350 //-----------------------------------------------------------------------------
01351 
01352 // WndProc hook (declared here because we will need access to ImGui_ImplGlfw_ViewportData)
01353 #ifdef _WIN32
01354 static ImGuiMouseSource GetMouseSourceFromMessageExtraInfo()
01355 {
01356     LPARAM extra_info = ::GetMessageExtraInfo();
01357     if ((extra_info & 0xFFFFFF80) == 0xFF515700)
01358         return ImGuiMouseSource_Pen;
01359     if ((extra_info & 0xFFFFFF80) == 0xFF515780)
01360         return ImGuiMouseSource_TouchScreen;
01361     return ImGuiMouseSource_Mouse;
01362 }
01363 static LRESULT CALLBACK ImGui_ImplGlfw_WndProc(HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam)
01364 {
01365     ImGui_ImplGlfw_Data* bd = ImGui_ImplGlfw_GetBackendData();
01366     WNDPROC prev_wndproc = bd->PrevWndProc;
01367     ImGuiViewport* viewport = (ImGuiViewport*)::GetPropA(hWnd, "IMGUI_VIEWPORT");
01368     if (viewport != NULL)
01369         if (ImGui_ImplGlfw_ViewportData* vd = (ImGui_ImplGlfw_ViewportData*)viewport->PlatformUserData)
01370             prev_wndproc = vd->PrevWndProc;
01371 
01372     switch (msg)
01373     {
01374         // GLFW doesn't allow to distinguish Mouse vs TouchScreen vs Pen.
01375         // Add support for Win32 (based on imgui_impl_win32), because we rely on _TouchScreen info to trickle inputs differently.
01376     case WM_MOUSEMOVE: case WM_NCMOUSEMOVE:
01377     case WM_LBUTTONDOWN: case WM_LBUTTONDBLCLK: case WM_LBUTTONUP:
01378     case WM_RBUTTONDOWN: case WM_RBUTTONDBLCLK: case WM_RBUTTONUP:
01379     case WM_MBUTTONDOWN: case WM_MBUTTONDBLCLK: case WM_MBUTTONUP:
01380     case WM_XBUTTONDOWN: case WM_XBUTTONDBLCLK: case WM_XBUTTONUP:
01381         ImGui::GetIO().AddMouseSourceEvent(GetMouseSourceFromMessageExtraInfo());
01382         break;
01383 
01384         // We have submitted https://github.com/glfw/glfw/pull/1568 to allow GLFW to support "transparent inputs".
01385         // In the meanwhile we implement custom per-platform workarounds here (FIXME-VIEWPORT: Implement same work-around for Linux/OSX!)
01386 #if !GLFW_HAS_MOUSE_PASSTHROUGH && GLFW_HAS_WINDOW_HOVERED
01387     case WM_NCHITTEST:
01388     {
01389         // Let mouse pass-through the window. This will allow the backend to call io.AddMouseViewportEvent() properly (which is OPTIONAL).
01390         // The ImGuiViewportFlags_NoInputs flag is set while dragging a viewport, as want to detect the window behind the one we are dragging.
01391         // If you cannot easily access those viewport flags from your windowing/event code: you may manually synchronize its state e.g. in
01392         // your main loop after calling UpdatePlatformWindows(). Iterate all viewports/platform windows and pass the flag to your windowing system.
01393         if (viewport && (viewport->Flags & ImGuiViewportFlags_NoInputs))
01394             return HTTRANSPARENT;
01395         break;
01396     }
01397 #endif
01398     }
01399     return ::CallWindowProcW(prev_wndproc, hWnd, msg, wParam, lParam);
01400 }
01401 #endif // #ifdef _WIN32
